const { Server } = require('@hocuspocus/server');
const { Redis } = require('@hocuspocus/extension-redis');
const jwt = require('jsonwebtoken');
const db = require('../db');

const server = Server.configure({
  port: 1234,
  extensions: [new Redis({ host: '127.0.0.1', port: 6379 })],

  async onAuthenticate(data) {
    const { token } = data;
    try {
      const payload = jwt.verify(token, process.env.JWT_SECRET);
      return { user: payload };
    } catch {
      throw new Error('Unauthorized');
    }
  },

  async onLoadDocument(data) {
    // Ensure caller is an authorized collaborator on data.documentName
    const doc = await db('documents')
      .join('document_collaborators', 'documents.id', '=', 'document_collaborators.document_id')
      .where({
        'documents.slug': data.documentName,
        'document_collaborators.user_id': data.context.user.id
      })
      .first();

    if (!doc) {
      throw new Error('Forbidden: Access denied to collaborative document');
    }

    return data.document;
  }
});

server.listen();
module.exports = server;
